name: Dependabot Auto Merge

on:
  pull_request_target:
    types: [opened, synchronize]
  workflow_run:
    workflows: ["Only CI/CT"]
    types: [completed]

permissions:
  pull-requests: write
  checks: read
  statuses: read
  contents: read

concurrency:
  group: dependabot-auto-merge-${{ github.event.pull_request.number || github.event.workflow_run.pull_requests[0].number }}
  cancel-in-progress: true

jobs:
  auto-merge:
    if: |
      (github.event_name == 'pull_request_target' && github.event.pull_request.user.login == 'dependabot[bot]') ||
      (github.event_name == 'workflow_run' && github.event.workflow_run.conclusion == 'success')
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Wait for status propagation
        if: github.event_name == 'workflow_run'
        run: sleep 5

      - name: Auto-approve and merge Dependabot PR
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = github.event_name === 'pull_request_target'
              ? github.event.pull_request.number
              : github.event.workflow_run.pull_requests[0]?.number;

            if (!prNumber) {
              core.info('No PR number found, skipping.');
              return;
            }

            try {
              // Fetch PR details
              const { data: pr } = await github.rest.pulls.get({
                owner: github.context.repo.owner,
                repo: github.context.repo.repo,
                pull_number: prNumber
              });

              // Ensure PR is from dependabot[bot]
              if (pr.user.login !== 'dependabot[bot]') {
                core.info(`PR #${prNumber} is not from dependabot[bot], skipping.`);
                return;
              }

              // Skip if already merged
              if (pr.merged) {
                core.info(`PR #${prNumber} is already merged, skipping.`);
                return;
              }

              // Check if bot already approved
              const { data: reviews } = await github.rest.pulls.listReviews({
                owner: github.context.repo.owner,
                repo: github.context.repo.repo,
                pull_number: prNumber
              });

              const botApproved = reviews.some(
                r => r.user.login === 'dependabot[bot]' && r.state === 'APPROVED'
              );

              if (botApproved) {
                core.info(`PR #${prNumber} already approved by dependabot[bot], skipping.`);
                return;
              }

              // Get combined status for the PR head SHA
              const { data: combinedStatus } = await github.rest.repos.getCombinedStatusForRef({
                owner: github.context.repo.owner,
                repo: github.context.repo.repo,
                ref: pr.head.sha
              });

              // Ensure there is at least one status check
              if (!combinedStatus.statuses || combinedStatus.statuses.length === 0) {
                core.info(`PR #${prNumber} has no status checks, skipping merge.`);
                return;
              }

              // Detect failed or cancelled checks
              const hasFailure = combinedStatus.statuses.some(
                s => s.state === 'failure' || s.state === 'error'
              );
              const hasCancelled = combinedStatus.statuses.some(
                s => s.state === 'cancelled'
              );

              if (hasFailure || hasCancelled) {
                core.info(`PR #${prNumber} has failed or cancelled checks, skipping merge.`);
                return;
              }

              // Ensure all checks are successful
              const allSuccess = combinedStatus.statuses.every(
                s => s.state === 'success'
              );

              if (!allSuccess) {
                core.info(`PR #${prNumber} has incomplete checks, skipping merge.`);
                return;
              }

              // Auto-approve the PR
              await github.rest.pulls.createReview({
                owner: github.context.repo.owner,
                repo: github.context.repo.repo,
                pull_number: prNumber,
                event: 'APPROVE',
                body: 'Auto-approval by Dependabot Auto Merge workflow.'
              });
              core.info(`PR #${prNumber} approved.`);

              // Merge the PR with squash
              await github.rest.pulls.merge({
                owner: github.context.repo.owner,
                repo: github.context.repo.repo,
                pull_number: prNumber,
                merge_method: 'squash',
                commit_title: `Merge Dependabot PR #${prNumber}`,
                commit_message: pr.title
              });
              core.info(`PR #${prNumber} merged with squash.`);
            } catch (error) {
              core.setFailed(`Error processing PR #${prNumber}: ${error.message}`);
            }
